using OrcaFacil.Application.Approvals;using OrcaFacil.Domain.Entities;
namespace OrcaFacil.UnitTests;
public sealed class ApprovalWorkflowServiceTests
{private readonly ApprovalWorkflowService service=new();[Fact]public void HighDiscountRequiresApproval(){var p=new DiscountPolicy{IsActive=true,MaxDiscountPercentWithoutApproval=10,MaxDiscountAmountWithoutApproval=1000};Assert.True(service.Evaluate(p,1000,101).Required);}[Fact]public void CreatorCannotSelfApproveWhenSeparationRequired(){var user=Guid.NewGuid();var r=new ApprovalRequest{RequestedByUserId=user,RequireDifferentApprover=true};Assert.Throws<InvalidOperationException>(()=>service.Approve(r,user));}[Fact]public void RejectionRequiresReason(){var r=new ApprovalRequest{RequestedByUserId=Guid.NewGuid()};Assert.Throws<ArgumentException>(()=>service.Reject(r,Guid.NewGuid()," "));}[Fact]public void PendingApprovalBlocksPublicProposal(){var r=new ApprovalRequest{Status=ApprovalStatus.Pending};var ex=Assert.Throws<InvalidOperationException>(()=>service.EnsurePublicProposalAllowed(r));Assert.Contains("aprovação interna",ex.Message);}[Fact]public void ApprovedRequestAllowsPublicProposal(){var r=new ApprovalRequest{Status=ApprovalStatus.Approved};service.EnsurePublicProposalAllowed(r);}}
